// =============================================================
// checksDocTable.test.mjs: the card table and the list of conditions in plugin/docs/checks.md match the card files.
//
// Why: the Checks tab's cards are files (plugin/scripts/orchestrator/checks-catalog/suggestions/), and checks.md has one
// row per card, generated by scripts/checks-doc-table.mjs. A card added, removed or changed without running the
// generator would leave the page saying something the tab does not do. This reads checks.md and the card files, and
// fails with the reasons and the command that writes the table again (npm run docs:checks). The other tests show that
// the check itself catches a missing card, a changed card, a row for no card and a condition with no sentence, on a
// copy of the catalog in a temporary folder.
// =============================================================
import { afterAll, describe, expect, it } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { CATALOG_DIR, COMMAND, DOC, PHRASES, between, MARKERS, phrase, problems, renderTable, rows, updated } from '../checks-doc-table.mjs';

const require = createRequire(import.meta.url);
const CATALOG = require('../../plugin/scripts/orchestrator/lib/checksCatalog.js');

const read = (f) => fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n');
const temporary = [];
afterAll(() => {
  for (const d of temporary) fs.rmSync(d, { recursive: true, force: true });
});

/** A copy of the plugin's catalog in a temporary folder, to add, change or remove a card in. */
function copyCatalog() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'checks-doc-table-'));
  temporary.push(dir);
  fs.cpSync(CATALOG_DIR, dir, { recursive: true });
  return dir;
}
const card = (dir, key) => path.join(dir, 'suggestions', `${key}.md`);

describe('the card table in plugin/docs/checks.md', () => {
  it(`matches the card files (if not: ${COMMAND})`, () => {
    const p = problems(read(DOC));
    expect(p, `plugin/docs/checks.md is out of date:\n- ${p.join('\n- ')}\nRun: ${COMMAND}`).toEqual([]);
  });

  it('has one row per card file in the plugin', () => {
    const files = fs.readdirSync(path.join(CATALOG_DIR, 'suggestions')).filter((f) => f.endsWith('.md'));
    const table = between(read(DOC), MARKERS.table) ?? '';
    for (const f of files) expect(table, `${f} in the table (run ${COMMAND})`).toContain(`(\`${f.slice(0, -3)}\`)`);
    expect(rows().length).toBe(files.length);
  });

  it('catches a card that is missing from the table', () => {
    const dir = copyCatalog();
    fs.writeFileSync(
      card(dir, 'new-card'),
      '---\ntitle: A new card\ncategory: tests\npriority: low\nwhen: found:test\nwhy: Because.\n---\n\n## Investigate\n\nX\n\n## Plan and build\n\nY\n',
    );
    const doc = updated(read(DOC));
    expect(problems(doc, { dir })).toContain('the card new-card is missing from the table');
  });

  it('catches a row that no longer says what the card says', () => {
    const dir = copyCatalog();
    const f = card(dir, 'coverage');
    fs.writeFileSync(f, read(f).replace('priority: low', 'priority: high'));
    expect(problems(updated(read(DOC)), { dir })).toContain('the row for coverage is out of date');
  });

  it('catches a row for a card that is gone', () => {
    const dir = copyCatalog();
    fs.rmSync(card(dir, 'coverage'));
    expect(problems(updated(read(DOC)), { dir })).toContain('the table has a row for coverage, which is no card');
  });

  it('a card with a condition the generator has no sentence for stops it, naming the file to change', () => {
    const dir = copyCatalog();
    const f = card(dir, 'coverage');
    // A condition the parser does not know is a card mistake; the generator stops on it like the tab lists it.
    fs.writeFileSync(f, read(f).replace('when: found:test, missing:coverage', 'when: found:test, no-such-condition'));
    expect(() => renderTable(dir)).toThrow(/no-such-condition/);
    expect(() => phrase('no-such-condition')).toThrow(/scripts\/checks-doc-table\.mjs PHRASES/);
  });
});

describe('the list of conditions in plugin/docs/checks.md', () => {
  it('has a sentence for every condition lib/checksCatalog.js knows, and none it does not', () => {
    expect(Object.keys(PHRASES).sort()).toEqual(Object.keys(CATALOG.CONDITIONS).sort());
  });

  it('every condition with an argument in the sentences is one the parser accepts', () => {
    for (const c of ['missing:test', 'found:test', 'not-in-ci:test', 'none-in-ci:migrate', 'off:x', 'ledger-due:x', 'ledger-guard-failed:x', 'ledger-recent:x']) {
      const t = CATALOG.parseTemplate(`---\ntitle: T\ncategory: tests\npriority: low\nwhen: ${c}\nwhy: W\naction: ask\n---\n## Ask Claude\nA\n`, 'k');
      expect(t.errors, c).toEqual([]);
    }
  });
});
